INSERT INTO t_message (id, public_id, conversation_id, parent_message_id, sender, text, error, created_at) VALUES (1, E'0b8bb7a9-37fe-4ab4-9f6a-26cecd37e508', 1, NULL, E'user', E'你好，请介绍一下你能做什么', false, E'2026-11-23 13:56:24');
INSERT INTO t_message (id, public_id, conversation_id, parent_message_id, sender, text, error, created_at) VALUES (2, E'41887703-c299-4e61-b5df-2f7a3783564a', 1, E'0b8bb7a9-37fe-4ab4-9f6a-26cecd37e508', E'agent', E'你好！我是「爆款选题助手」，隶属于流量部门，很高兴为你服务！我的主要功能是帮你挖掘和策划具有爆款潜力的选题，从而提升内容的流量表现。以下是我能为你做的事情：\n\n1. **热点追踪**：根据当前的热点趋势、节日节点或流行话题，为你推荐适合的选题方向。\n2. **用户需求分析**：通过分析目标用户的兴趣点和需求，帮你找到更能吸引他们的内容主题。\n3. **竞品分析**：研究和拆解同行或竞品的爆款内容，提炼出成功的选题思路。\n4. **创意策划**：结合你的领域特点，提供有创意、有吸引力的选题建议。\n5. **标题优化**：为你的选题提供吸引力强的标题建议，提升点击率。\n6. **内容结构建议**：帮你规划内容的结构和呈现形式，让选题更具传播力。\n\n如果你有具体的领域、目标人群或内容方向，可以告诉我，我会为你量身定制选题建议！你有什么需求呢？', false, E'2026-11-23 13:56:27');
INSERT INTO t_message (id, public_id, conversation_id, parent_message_id, sender, text, error, created_at) VALUES (3, E'dc317d1e-9e81-4f07-a0ee-3aa8ee9a3894', 2, NULL, E'user', E'hello', false, E'2026-11-23 14:29:41');
INSERT INTO t_message (id, public_id, conversation_id, parent_message_id, sender, text, error, created_at) VALUES (4, E'1e4a75e2-46ab-484b-a31e-142da5350b49', 2, E'dc317d1e-9e81-4f07-a0ee-3aa8ee9a3894', E'agent', E'你好呀！我是AI漫剧编剧，很高兴见到你～\n\n我可以帮你做这些事：\n- 📝 **剧本创作**：漫剧分镜脚本、台词、旁白\n- �#️⃣ **人设与世界观**：角色设定、剧情框架\n- 🎬 **分镜设计**：镜头语言、画面节奏建议\n- 💡 **创意脑暴**：剧情走向、反转设计、爽点安排\n\n想聊点什么？是有具体的漫剧项目要做，还是先随便聊聊灵感？😊', false, E'2026-11-23 14:29:44');
